using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.EntityFrameworkCore;
using System;

namespace ContosoUniversity.Tests.Helpers
{
    public static class TestHelpers
    {
        public static SchoolContext CreateInMemoryContext()
        {
            var options = new DbContextOptionsBuilder<SchoolContext>()
                .UseInMemoryDatabase(databaseName: Guid.NewGuid().ToString())
                .Options;
            var context = new SchoolContext(options);
            return context;
        }

        public static SchoolContext CreateSeededContext()
        {
            var context = CreateInMemoryContext();
            SeedData(context);
            return context;
        }

        public static void SeedData(SchoolContext context)
        {
            var instructor1 = new Instructor
            {
                ID = 1, FirstMidName = "Kim", LastName = "Abercrombie",
                HireDate = new DateTime(1995, 3, 11)
            };
            var instructor2 = new Instructor
            {
                ID = 2, FirstMidName = "Fadi", LastName = "Fakhouri",
                HireDate = new DateTime(2002, 7, 6)
            };
            context.Instructors.AddRange(instructor1, instructor2);

            var dept1 = new Department
            {
                DepartmentID = 1, Name = "English", Budget = 350000,
                StartDate = new DateTime(2007, 9, 1), InstructorID = 1
            };
            var dept2 = new Department
            {
                DepartmentID = 2, Name = "Mathematics", Budget = 100000,
                StartDate = new DateTime(2007, 9, 1), InstructorID = 2
            };
            context.Departments.AddRange(dept1, dept2);

            var course1 = new Course
            {
                CourseID = 1050, Title = "Chemistry", Credits = 3, DepartmentID = 1
            };
            var course2 = new Course
            {
                CourseID = 4022, Title = "Microeconomics", Credits = 3, DepartmentID = 2
            };
            context.Courses.AddRange(course1, course2);

            var student1 = new Student
            {
                ID = 10, FirstMidName = "Carson", LastName = "Alexander",
                EnrollmentDate = new DateTime(2010, 9, 1)
            };
            var student2 = new Student
            {
                ID = 11, FirstMidName = "Meredith", LastName = "Alonso",
                EnrollmentDate = new DateTime(2012, 9, 1)
            };
            var student3 = new Student
            {
                ID = 12, FirstMidName = "Arturo", LastName = "Anand",
                EnrollmentDate = new DateTime(2013, 9, 1)
            };
            context.Students.AddRange(student1, student2, student3);

            context.Enrollments.Add(new Enrollment
            {
                EnrollmentID = 1, StudentID = 10, CourseID = 1050, Grade = Grade.A
            });

            context.SaveChanges();
        }
    }
}

