        public void Delete_GET_InvalidId_ReturnsNotFound()
        {
            var result = _controller.Delete(9999);

            Assert.IsType<NotFoundResult>(result);
        }

        // === DeleteConfirmed Tests ===

        [Fact]
        public void DeleteConfirmed_ValidId_RemovesDepartmentAndRedirects()
        {
            var result = _controller.DeleteConfirmed(1);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            Assert.Null(_context.Departments.Find(1));
        }

        [Fact]
        public void DeleteConfirmed_ValidId_DecreasesDepartmentCount()
        {
            var countBefore = _context.Departments.Count();

            _controller.DeleteConfirmed(1);

            Assert.Equal(countBefore - 1, _context.Departments.Count());
        }

        private void DetachDepartment(int id)
        {
            var existing = _context.Departments.Find(id);
            if (existing != null)
                _context.Entry(existing).State = EntityState.Detached;
        }
    }
}

