using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Models.SchoolViewModels;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.ViewFeatures;
using Microsoft.EntityFrameworkCore;
using Moq;
using System;
using System.Collections.Generic;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class InstructorsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly InstructorsController _controller;

        public InstructorsControllerTests()
        {
            _context = TestHelpers.CreateInMemoryContext();
            SeedInstructorData(_context);
            _controller = CreateController(_context);
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        private static InstructorsController CreateController(SchoolContext context)
        {
            var controller = new InstructorsController(context);
            controller.ControllerContext = new ControllerContext
            {
                HttpContext = new DefaultHttpContext()
            };
            controller.TempData = new TempDataDictionary(
                new DefaultHttpContext(), Mock.Of<ITempDataProvider>());
            return controller;
        }

        private static void SeedInstructorData(SchoolContext context)
        {
            var dept = new Department
            {
                DepartmentID = 1, Name = "English", Budget = 350000,
                StartDate = new DateTime(2007, 9, 1)
            };
            context.Departments.Add(dept);

            var instructor1 = new Instructor
            {
                ID = 1, FirstMidName = "Kim", LastName = "Abercrombie",
                HireDate = new DateTime(1995, 3, 11),
                CourseAssignments = new List<CourseAssignment>(),
                OfficeAssignment = new OfficeAssignment { InstructorID = 1, Location = "Smith 17" }
            };
            var instructor2 = new Instructor
            {
                ID = 2, FirstMidName = "Fadi", LastName = "Fakhouri",
                HireDate = new DateTime(2002, 7, 6),
                CourseAssignments = new List<CourseAssignment>()
            };
            context.Instructors.AddRange(instructor1, instructor2);

            var course1 = new Course
            {
                CourseID = 1050, Title = "Chemistry", Credits = 3, DepartmentID = 1,
                Enrollments = new List<Enrollment>(),
                CourseAssignments = new List<CourseAssignment>()
            };
            var course2 = new Course
            {
                CourseID = 2021, Title = "Composition", Credits = 3, DepartmentID = 1,
                Enrollments = new List<Enrollment>(),
                CourseAssignments = new List<CourseAssignment>()
            };
            context.Courses.AddRange(course1, course2);

            var ca = new CourseAssignment { InstructorID = 1, CourseID = 1050 };
            context.CourseAssignments.Add(ca);
            instructor1.CourseAssignments.Add(ca);
            course1.CourseAssignments.Add(ca);

            // Explicitly set the department's InstructorID
            dept.InstructorID = 1;

            context.SaveChanges();
        }

        // === Index Tests ===

        [Fact]
        public void Index_NoParameters_ReturnsViewWithInstructors()
        {
            var result = _controller.Index(null, null) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<InstructorIndexData>(result.Model);
            Assert.Equal(2, model.Instructors.Count());
        }

        [Fact]
        public void Index_WithInstructorId_PopulatesCourses()
        {
            var result = _controller.Index(1, null) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<InstructorIndexData>(result.Model);
            Assert.NotNull(model.Courses);
            Assert.Single(model.Courses);
            Assert.Equal("Chemistry", model.Courses.First().Title);
        }

        [Fact]
        public void Index_WithInstructorId_SetsViewBagInstructorID()
        {
            _controller.Index(1, null);

            Assert.Equal(1, (int)_controller.ViewBag.InstructorID);
        }

        [Fact]
        public void Index_WithCourseId_PopulatesEnrollments()
        {
            var result = _controller.Index(1, 1050) as ViewResult;

            var model = Assert.IsType<InstructorIndexData>(result!.Model);
            Assert.NotNull(model.Enrollments);
        }

        // === Details Tests ===

        [Fact]
        public void Details_NullId_ReturnsBadRequest()
        {
            var result = _controller.Details(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Details_ValidId_ReturnsViewWithInstructor()
        {
            var result = _controller.Details(1) as ViewResult;

            Assert.NotNull(result);
            var instructor = Assert.IsType<Instructor>(result.Model);
            Assert.Equal("Abercrombie", instructor.LastName);
        }

        [Fact]
        public void Details_InvalidId_ReturnsNotFound()
        {
            var result = _controller.Details(9999);

            Assert.IsType<NotFoundResult>(result);
        }

        // === Create (GET) Tests ===

        [Fact]
        public void Create_GET_ReturnsViewWithInstructorAndCourseData()
        {
            var result = _controller.Create() as ViewResult;

            Assert.NotNull(result);
            var instructor = Assert.IsType<Instructor>(result.Model);
            Assert.NotNull(instructor.CourseAssignments);
            Assert.NotNull(_controller.ViewBag.Courses);
        }

        // === Create (POST) Tests ===

        [Fact]
        public void Create_POST_ValidInstructor_RedirectsToIndex()
        {
            var instructor = new Instructor
            {
                FirstMidName = "New",
                LastName = "Instructor",
                HireDate = new DateTime(2023, 1, 15),
                CourseAssignments = new List<CourseAssignment>()
            };

            var result = _controller.Create(instructor, null!);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
        }

        [Fact]
        public void Create_POST_ValidInstructor_AddsToDatabase()
        {
            var instructor = new Instructor
            {
                FirstMidName = "New",
                LastName = "Prof",
                HireDate = new DateTime(2023, 1, 15),
                CourseAssignments = new List<CourseAssignment>()
            };

            _controller.Create(instructor, null!);

            Assert.Equal(3, _context.Instructors.Count());
        }

        [Fact]
        public void Create_POST_WithSelectedCourses_AssignsCourses()
        {
            var instructor = new Instructor
            {
                FirstMidName = "Course",
                LastName = "Assigned",
                HireDate = new DateTime(2023, 1, 15),
                CourseAssignments = new List<CourseAssignment>()
            };

            _controller.Create(instructor, new[] { "1050", "2021" });

            var savedInstructor = _context.Instructors
                .Include(i => i.CourseAssignments)
                .Single(i => i.LastName == "Assigned");
            Assert.Equal(2, savedInstructor.CourseAssignments.Count);
        }

        [Fact]
        public void Create_POST_InvalidModelState_ReturnsViewWithCourseData()
        {
            _controller.ModelState.AddModelError("LastName", "Required");
            var instructor = new Instructor
            {
                CourseAssignments = new List<CourseAssignment>()
            };

            var result = _controller.Create(instructor, null!) as ViewResult;

            Assert.NotNull(result);
            Assert.NotNull(_controller.ViewBag.Courses);
        }

        // === Edit (GET) Tests ===

        [Fact]
        public void Edit_GET_NullId_ReturnsBadRequest()
        {
            var result = _controller.Edit((int?)null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Edit_GET_ValidId_ReturnsViewWithInstructor()
        {
            var result = _controller.Edit((int?)1) as ViewResult;

            Assert.NotNull(result);
            // The model is an Instructor
            var instructor = Assert.IsType<Instructor>(result.Model);
            Assert.Equal("Abercrombie", instructor.LastName);
        }

        // === Delete (GET) Tests ===

        [Fact]
        public void Delete_GET_NullId_ReturnsBadRequest()
        {
            var result = _controller.Delete(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Delete_GET_ValidId_ReturnsViewWithInstructor()
        {
            var result = _controller.Delete(1) as ViewResult;

            Assert.NotNull(result);
            var instructor = Assert.IsType<Instructor>(result.Model);
            Assert.Equal("Abercrombie", instructor.LastName);
        }

        [Fact]
        public void Delete_GET_InvalidId_ReturnsNotFound()
        {
            var result = _controller.Delete(9999);

            Assert.IsType<NotFoundResult>(result);
        }

        // === DeleteConfirmed Tests ===

        [Fact]
        public void DeleteConfirmed_ValidId_RemovesInstructorAndRedirects()
        {
            var result = _controller.DeleteConfirmed(1);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            Assert.Null(_context.Instructors.Find(1));
        }

        [Fact]
        public void DeleteConfirmed_InstructorIsDeptAdmin_ClearsDepartmentAdministrator()
        {
            // Instructor 1 is admin of department 1
            _controller.DeleteConfirmed(1);

            var dept = _context.Departments.Find(1);
            Assert.Null(dept!.InstructorID);
        }

        [Fact]
        public void DeleteConfirmed_DecreasesInstructorCount()
        {
            var countBefore = _context.Instructors.Count();

            _controller.DeleteConfirmed(2);

            Assert.Equal(countBefore - 1, _context.Instructors.Count());
        }
    }
}

