using ContosoUniversity.Models;
using Xunit;

namespace ContosoUniversity.Tests.Models
{
    public class PersonTests
    {
        [Theory]
        [InlineData("Doe", "John", "Doe, John")]
        [InlineData("Smith", "Jane", "Smith, Jane")]
        [InlineData("O'Brien", "Mary", "O'Brien, Mary")]
        public void FullName_CombinesLastAndFirstName(string lastName, string firstName, string expected)
        {
            var student = new Student { LastName = lastName, FirstMidName = firstName };

            Assert.Equal(expected, student.FullName);
        }

        [Fact]
        public void FullName_WorksForInstructor()
        {
            var instructor = new Instructor { LastName = "Abercrombie", FirstMidName = "Kim" };

            Assert.Equal("Abercrombie, Kim", instructor.FullName);
        }
    }

    public class ErrorViewModelTests
    {
        [Fact]
        public void ShowRequestId_ReturnsFalse_WhenRequestIdIsNull()
        {
            var model = new ErrorViewModel { RequestId = null };

            Assert.False(model.ShowRequestId);
        }

        [Fact]
        public void ShowRequestId_ReturnsFalse_WhenRequestIdIsEmpty()
        {
            var model = new ErrorViewModel { RequestId = "" };

            Assert.False(model.ShowRequestId);
        }

        [Fact]
        public void ShowRequestId_ReturnsTrue_WhenRequestIdHasValue()
        {
            var model = new ErrorViewModel { RequestId = "abc-123" };

            Assert.True(model.ShowRequestId);
        }
    }

    public class NotificationModelTests
    {
        [Fact]
        public void Notification_DefaultValues()
        {
            var notification = new Notification();

            Assert.Equal(0, notification.Id);
            Assert.False(notification.IsRead);
            Assert.Null(notification.ReadAt);
        }

        [Fact]
        public void Notification_PropertiesCanBeSet()
        {
            var now = System.DateTime.Now;
            var notification = new Notification
            {
                Id = 1,
                EntityType = "Student",
                EntityId = "42",
                Operation = "CREATE",
                Message = "Student created",
                CreatedAt = now,
                CreatedBy = "Admin",
                IsRead = true,
                ReadAt = now
            };

            Assert.Equal(1, notification.Id);
            Assert.Equal("Student", notification.EntityType);
            Assert.Equal("42", notification.EntityId);
            Assert.Equal("CREATE", notification.Operation);
            Assert.Equal("Student created", notification.Message);
            Assert.Equal(now, notification.CreatedAt);
            Assert.Equal("Admin", notification.CreatedBy);
            Assert.True(notification.IsRead);
            Assert.Equal(now, notification.ReadAt);
        }
    }

    public class EntityOperationTests
    {
        [Theory]
